import{_ as d,o as r,c as a,ai as e}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"CI/CD 实战与面试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devops/cicd-interview.md","filePath":"guide/devops/cicd-interview.md"}'),i={name:"guide/devops/cicd-interview.md"};function o(l,t,n,h,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ci-cd-实战与面试" tabindex="-1">CI/CD 实战与面试 <a class="header-anchor" href="#ci-cd-实战与面试" aria-label="Permalink to “CI/CD 实战与面试”">​</a></h1><p>目标：讲清流水线在干什么，并能描述一条「提交代码 → 构建测试 → 部署」的最小路径。</p><hr><h2 id="面试高频问法" tabindex="-1">面试高频问法 <a class="header-anchor" href="#面试高频问法" aria-label="Permalink to “面试高频问法”">​</a></h2><ol><li>什么是 CI？什么是 CD？你们流水线有哪些阶段？</li><li>你们常用哪种 CI/CD 方式？为什么适合你们场景？</li><li>一次提交后，你们服务器/环境怎么更新？</li><li>构建失败你怎么查？发布失败怎么回滚？</li><li>有没有做过分支策略？（main / feature / release）</li><li>密钥、环境变量怎么管理？会不会打进镜像？</li><li>持续交付和持续部署有什么区别？生产要不要人工确认？</li></ol><hr><h2 id="口述参考-短版" tabindex="-1">口述参考（短版） <a class="header-anchor" href="#口述参考-短版" aria-label="Permalink to “口述参考（短版）”">​</a></h2><p><strong>CI：</strong> 代码合并后自动构建 + 跑测试，尽早发现问题。</p><p><strong>CD：</strong> 把可发布产物自动推到测试/预发；生产是否全自动取决于团队，很多公司保留人工确认。</p><p><strong>一条典型流水线：</strong><br> checkout → 安装依赖/编译 → 单测 → 打包（jar/镜像）→ 部署到环境 → 健康检查。</p><p><strong>回滚：</strong> 保留上一版产物/镜像 tag；出问题切回上一版本并观察健康检查与日志。</p><hr><h2 id="常用方式有哪些-各自适用什么场景" tabindex="-1">常用方式有哪些，各自适用什么场景 <a class="header-anchor" href="#常用方式有哪些-各自适用什么场景" aria-label="Permalink to “常用方式有哪些，各自适用什么场景”">​</a></h2><p>面试别只背工具名，要说清：<strong>我们用什么、为什么适合这个团队、边界在哪。</strong></p><h3 id="_1-按工具平台-选一个你真实接触过的深讲" tabindex="-1">1）按工具平台（选一个你真实接触过的深讲） <a class="header-anchor" href="#_1-按工具平台-选一个你真实接触过的深讲" aria-label="Permalink to “1）按工具平台（选一个你真实接触过的深讲）”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>常见形态</th><th>更适合</th><th>不太适合 / 注意</th></tr></thead><tbody><tr><td><strong>GitHub Actions</strong></td><td>仓库内 YAML，按 push / PR / tag 触发</td><td>开源、GitHub 托管、个人/小团队、本站这种静态站发布</td><td>强内网隔离、极重的私有构建机需求</td></tr><tr><td><strong>GitLab CI</strong></td><td><code>.gitlab-ci.yml</code> + Runner</td><td>自建 GitLab、代码与流水线一体、国内很多企业仓库</td><td>Runner 要自己维护；权限和缓存要规划</td></tr><tr><td><strong>Jenkins</strong></td><td>可视化 Job / Pipeline as Code</td><td>老项目、复杂多仓库编排、公司已有 Jenkins 机房</td><td>插件多易变脆；要从零选型时不一定是首选</td></tr><tr><td><strong>云厂商流水线</strong>（阿里云效 / 腾讯 Coding / 华为等）</td><td>和云主机、镜像仓库、K8s 绑得紧</td><td>业务已在该云、要少运维</td><td>易被厂商锁定；换云成本高</td></tr><tr><td><strong>手动 / 半自动</strong></td><td>本机构建 + 脚本上传 / 宝塔 / 远程 ssh</td><td>早期项目、一人维护、发布频率低</td><td>难复现、难协作；面试要承认并说清演进方向</td></tr></tbody></table><p>口述模板：</p><blockquote><p>我们常用的是 XXX。触发方式是合并到某分支后自动构建打包，测试环境自动部署；生产需要人工点确认。选它是因为仓库就在这套体系里，维护成本低。</p></blockquote><h3 id="_2-按发布节奏-ci-之后「送到哪、谁点确认」" tabindex="-1">2）按发布节奏（CI 之后「送到哪、谁点确认」） <a class="header-anchor" href="#_2-按发布节奏-ci-之后「送到哪、谁点确认」" aria-label="Permalink to “2）按发布节奏（CI 之后「送到哪、谁点确认」）”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>含义</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>只做 CI</strong></td><td>自动构建 + 测试，部署仍人工</td><td>规范刚起步；生产变更敏感；人少但要先保证「合并不烂」</td></tr><tr><td><strong>Continuous Delivery（持续交付）</strong></td><td>随时可发布，生产通常人工确认</td><td>大多数业务系统、MES / 企业后台——<strong>最常见、也好讲</strong></td></tr><tr><td><strong>Continuous Deployment（持续部署）</strong></td><td>通过流水线后自动上生产</td><td>强自动化、完善测试与监控的团队；小工具/静态站也可以</td></tr><tr><td><strong>定时发布</strong></td><td>每天/每周固定窗口发版</td><td>强监管、需变更窗口；避免深夜随意发</td></tr></tbody></table><p>注意：面试里 <strong>Delivery ≠ Deployment</strong>。很多公司说「我们做了 CD」，实际是 Delivery（可发，但生产要人点）。</p><h3 id="_3-按部署策略-生产怎么换版本" tabindex="-1">3）按部署策略（生产怎么换版本） <a class="header-anchor" href="#_3-按部署策略-生产怎么换版本" aria-label="Permalink to “3）按部署策略（生产怎么换版本）”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>怎么做</th><th>适用场景</th><th>代价</th></tr></thead><tbody><tr><td><strong>停机更新</strong></td><td>停旧 → 上新 → 验证</td><td>内部系统、可接受短暂停机、发布少</td><td>简单，但有中断</td></tr><tr><td><strong>滚动更新</strong></td><td>分批替换实例</td><td>多实例服务、要不停服</td><td>要健康检查；兼容旧新并存</td></tr><tr><td><strong>蓝绿部署</strong></td><td>两套环境切换流量</td><td>要快速回滚、发布窗口紧</td><td>资源占用约翻倍</td></tr><tr><td><strong>金丝雀 / 灰度</strong></td><td>先放一小部分流量</td><td>用户多、风险高、要观察指标</td><td>要网关/流量与监控配合</td></tr></tbody></table><p>结合你的方向可以这样说：</p><blockquote><p>企业业务系统和 MES 类项目，我更常见的是 <strong>持续交付 + 测试环境自动部署 + 生产人工确认</strong>；实例不多时滚动或短停机更新都能接受。蓝绿/灰度要有多实例和流量切换能力才划算。</p></blockquote><h3 id="_4-按触发方式-流水线什么时候跑" tabindex="-1">4）按触发方式（流水线什么时候跑） <a class="header-anchor" href="#_4-按触发方式-流水线什么时候跑" aria-label="Permalink to “4）按触发方式（流水线什么时候跑）”">​</a></h3><table tabindex="0"><thead><tr><th>触发</th><th>适用</th></tr></thead><tbody><tr><td><strong>Push / 合并到开发分支</strong></td><td>日常 CI：编译、单测、打测试包</td></tr><tr><td><strong>Merge Request / Pull Request</strong></td><td>合入前卡质量（必跑检查）</td></tr><tr><td><strong>打 Tag / Release</strong></td><td>出正式版本、部署预发/生产</td></tr><tr><td><strong>手动点击（Manual job）</strong></td><td>生产发布、危险操作、数据迁移</td></tr><tr><td><strong>定时（Cron）</strong></td><td>夜间全量回归、定期构建依赖缓存</td></tr></tbody></table><hr><h2 id="实战-你要能讲清的最小落地" tabindex="-1">实战：你要能讲清的最小落地 <a class="header-anchor" href="#实战-你要能讲清的最小落地" aria-label="Permalink to “实战：你要能讲清的最小落地”">​</a></h2><p>不必背 Jenkins 全插件。抓住你真实用过的一种即可（GitHub Actions / GitLab CI / Jenkins），并用上一节的表说清「为什么选它、发布到哪一步自动、哪一步要人」。</p><h3 id="流水线阶段-按这个记" tabindex="-1">流水线阶段（按这个记） <a class="header-anchor" href="#流水线阶段-按这个记" aria-label="Permalink to “流水线阶段（按这个记）”">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>失败了怎么办</th></tr></thead><tbody><tr><td>构建</td><td>编译、打 jar/镜像</td><td>看编译日志、依赖、JDK 版本</td></tr><tr><td>测试</td><td>单测/关键冒烟</td><td>先修测试或确认是否环境不稳</td></tr><tr><td>发布</td><td>拷贝产物或拉镜像启动</td><td>回滚上一版本、看启动日志</td></tr><tr><td>验证</td><td>健康检查、核心接口探活</td><td>不通过则停止放量/回滚</td></tr></tbody></table><h3 id="口述模板-套你自己的项目" tabindex="-1">口述模板（套你自己的项目） <a class="header-anchor" href="#口述模板-套你自己的项目" aria-label="Permalink to “口述模板（套你自己的项目）”">​</a></h3><blockquote><p>我们一般是提交到主开发分支后触发流水线：先构建打包，再跑基础测试，通过后部署到测试环境。生产发布会确认版本号。出问题优先看流水线日志和容器/服务启动日志，必要时回滚到上一个稳定包。</p></blockquote><h3 id="安全底线-加分" tabindex="-1">安全底线（加分） <a class="header-anchor" href="#安全底线-加分" aria-label="Permalink to “安全底线（加分）”">​</a></h3><ul><li>密码、Token 走环境变量/密钥管理，不写死在仓库</li><li>不同环境（dev/test/prod）配置分离</li><li>镜像打 tag（别只会 <code>latest</code>）</li></ul><hr><h2 id="结合你简历怎么讲" tabindex="-1">结合你简历怎么讲 <a class="header-anchor" href="#结合你简历怎么讲" aria-label="Permalink to “结合你简历怎么讲”">​</a></h2><p>若有 Docker + CI/CD（如 MES）：</p><blockquote><p>依赖服务容器化，业务包通过流水线构建；发布后看服务是否起来、关键接口是否通。发布异常会停更并回滚。</p></blockquote><p>没完整流水线也如实说：</p><blockquote><p>目前更多是手动/半自动发布，但我清楚标准流水线该有构建、测试、部署、回滚，正在往自动化补齐。</p></blockquote><p>比硬编一整套 Jenkins 更稳。</p><hr><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to “常见坑”">​</a></h2><ul><li>「流水线绿了但服务没起来」——缺健康检查</li><li>本地能过、CI 失败——JDK/Node 版本不一致</li><li>配置打进镜像——换环境要重新构建，还容易泄密</li></ul><hr><h2 id="自测清单" tabindex="-1">自测清单 <a class="header-anchor" href="#自测清单" aria-label="Permalink to “自测清单”">​</a></h2><ul><li>[ ] 能画/能说 5 个阶段：取代码→构建→测试→部署→验证</li><li>[ ] 能说出至少 2 种常用平台，并各举一个适用场景</li><li>[ ] 能区分持续交付 vs 持续部署，以及你们生产要不要人点确认</li><li>[ ] 能说出停机 / 滚动 / 蓝绿大致适用什么情况</li><li>[ ] 能说一次构建失败或发布回滚经历（真实即可）</li><li>[ ] 知道密钥不该进 Git</li><li>[ ] 能区分 CI 和 CD 各解决什么问题</li></ul>',49)])])}const p=d(i,[["render",o]]);export{g as __pageData,p as default};
